const title=value=>value?(FA_TERMS[String(value)]||String(value).replace(/\b\w/g,c=>c.toUpperCase())):'';
const esc=value=>String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
