function renderInstructions() {
  const exercise = state.activeExercise;
  if (!exercise) return;
  const steps = exercise.instruction_steps?.en;
  const text = exercise.instructions?.en || 'Instructions are not available.';
  $('#modalInstructions').innerHTML = Array.isArray(steps) && steps.length
    ? `<div class="step-list">${steps.map((step, index) => `<div class="step"><span>${index + 1}</span><div>${esc(step)}</div></div>`).join('')}</div>`
    : `<p class="instructions">${esc(text)}</p>`;
}
function updateModalProgress(exerciseId) {
  const latest = latestLogFor(exerciseId);
  $('#modalProgressSummary').textContent = latest ? `Last: ${formatProgress(latest)}` : 'No progress logged yet';
}
function resetModalScrollPosition() {
  $('.modal').scrollTop = 0;
  $('.modal-content').scrollTop = 0;
}
function openModal(exercise, returnFocus = document.activeElement) {
  state.activeExercise = exercise;
  $('#modalKicker').textContent = `${title(exercise.category)} · Exercise #${exercise.id}`;
  $('#modalTitle').textContent = exercise.name;
  $('#modalBadges').innerHTML = [exercise.target, exercise.equipment, exercise.body_part].filter(Boolean).map((value, index) => `<span class="badge${index === 0 ? ' primary' : ''}">${esc(title(value))}</span>`).join('');
  $('#modalSecondary').innerHTML = (exercise.secondary_muscles || []).length
    ? exercise.secondary_muscles.map((value) => `<span class="badge">${esc(title(value))}</span>`).join('')
    : '<span class="source">No secondary muscles listed</span>';
  const image = $('#modalImage');
  const fallback = image.nextElementSibling;
  image.style.display = 'block';
  fallback.style.display = 'none';
  image.src = exercise.gif_url || exercise.image;
  image.alt = `Demonstration of ${exercise.name}`;
  image.onerror = () => imageFallback(image);
  renderInstructions();
  updateModalProgress(exercise.id);
  const modalLike = $('#modalLikeExercise');
  modalLike.classList.toggle('saved', state.saved.has(exercise.id));
  modalLike.setAttribute('aria-pressed', String(state.saved.has(exercise.id)));
  modalLike.setAttribute('aria-label', `${state.saved.has(exercise.id) ? 'Remove from' : 'Add to'} saved exercises`);
  resetModalScrollPosition();
  openOverlay('modal', returnFocus);
  requestAnimationFrame(resetModalScrollPosition);
}
function closeModal(restoreFocus = true) {
  state.activeExercise = null;
  closeOverlay('modal', restoreFocus);
}

function resetProgressDraft() {
  Object.assign(state.progress.draft, { sets: DEFAULTS.sets, reps: DEFAULTS.reps, weight: DEFAULTS.weight, notes: '' });
  $('#progressNotes').value = '';
}
function persistProgress() {
  writeStorage(STORAGE_KEYS.progress, state.progress.logs);
}
function normalizeImportedProgressLog(log,index){
  if(!log||!VALID_EXERCISE_IDS.has(String(log.exerciseId).replace(/^#/,''))||!isValidProgressDate(log.date))return null;
  const idTimestamp=String(log.id||'').match(/\d{10,}/)?.[0],timestamp=Number(log.timestamp??log.createdAt??idTimestamp)||Date.now()+index;
  return{id:String(log.id||timestamp),exerciseId:String(log.exerciseId).replace(/^#/,''),date:String(log.date),sets:clamp(log.sets,1,LIMITS.sets),reps:clamp(log.reps,1,LIMITS.reps),weight:log.weight===''||log.weight==null?null:Math.min(LIMITS.weight,Math.max(0,Number(log.weight)||0)),notes:String(log.notes||'').slice(0,LIMITS.notes),createdAt:timestamp};
}
function progressLogToText(log){
  const exercise=EXERCISES.find(item=>item.id===log.exerciseId),timestamp=Number(log.createdAt)||Date.now(),numericId=String(log.id||'').match(/\d{10,}/)?.[0]||String(timestamp);
  return[`exercise: ${JSON.stringify(title(exercise?.name||'Unknown exercise'))}`,`exerciseId: #${log.exerciseId}`,`date: ${log.date}`,`sets: ${log.sets}`,`reps: ${log.reps}`,`weight: ${log.weight??''}`,`notes: ${String(log.notes||'').replace(/\s+/g,' ').trim()}`,`id: ${numericId}`].join('\n');
}
function progressLogsToText(logs=state.progress.logs){return logs.map(progressLogToText).join('\n\n')}
function parseProgressLogText(text){
  const raw=String(text||'').trim();
  if(!raw)throw new Error('Empty');
  if(raw.startsWith('[')){
    const value=JSON.parse(raw);
    if(!Array.isArray(value))throw new Error('Expected an array');
    const logs=value.map(normalizeImportedProgressLog).filter(Boolean);
    if(value.length&&!logs.length)throw new Error('No valid logs');
    return logs;
  }
  const blocks=raw.split(/(?=^exercise\s*:)/gim).map(block=>block.trim()).filter(Boolean),
        value=blocks.map(block=>{
          const fields={};
          block.split(/\r?\n/).forEach(line=>{
            const match=line.match(/^([A-Za-z]+)\s*:\s*(.*)$/);
            if(match)fields[match[1].toLowerCase()]=match[2].trim();
          });
          return{exerciseId:fields.exerciseid,date:fields.date,sets:fields.sets,reps:fields.reps,weight:fields.weight,notes:fields.notes,id:fields.id,timestamp:fields.timestamp};
        });
  const logs=value.map(normalizeImportedProgressLog).filter(Boolean);
  if(value.length&&!logs.length)throw new Error('No valid logs');
  return logs;
}
function closeProgressLogPaste(){
  $('#progressLogPaste').hidden=true;
  $('#progressLogPasteText').value='';
}
function closeProgressSettings(){
  $('#progressSettingsMenu').hidden=true;
  $('#progressSettingsBtn').setAttribute('aria-expanded','false');
  closeProgressLogPaste();
}
function toggleProgressSettings(){
  const willOpen=$('#progressSettingsMenu').hidden;
  closeProgressSettings();
  if(willOpen){
    $('#progressSettingsMenu').hidden=false;
    $('#progressSettingsBtn').setAttribute('aria-expanded','true');
    $('#progressWeekStart').value=String(state.progressPreferences.firstDay);
    syncCustomSelect($('#progressWeekStart'));
  }
}
function showProgressLogPaste(text=''){
  $('#progressLogPaste').hidden=false;
  $('#progressLogPasteText').value=text;
  requestAnimationFrame(()=>{$('#progressLogPasteText').focus();if(text)$('#progressLogPasteText').select();});
}
async function copyProgressLog(){
  if(!state.progress.logs.length)return toast('No progress to copy');
  const text=progressLogsToText();
  try{await navigator.clipboard.writeText(text);toast('Progress log copied');}
  catch{showProgressLogPaste(text);toast('Select and copy the text');}
}
function importProgressLog(mode='replace'){
  try{
    const logs=parseProgressLogText($('#progressLogPasteText').value);
    if(mode==='add'){
      const existingIds=new Set(state.progress.logs.map(log=>String(log.id)));
      const additions=[];
      logs.forEach(log=>{if(existingIds.has(String(log.id)))return;existingIds.add(String(log.id));additions.push(log);});
      if(!additions.length)return toast('No new progress entries to add');
      state.progress.logs.push(...additions);
      persistProgress();
      state.dashboard.selectedDate=null;
      renderProgressHistory('recent');
      closeProgressLogPaste();
      if(state.loggedOnly)render();
      toast(`${additions.length} progress entr${additions.length===1?'y':'ies'} added`);
      return;
    }
    if(state.progress.logs.length&&!confirm('Replace the current progress history?'))return;
    state.progress.logs=logs;
    persistProgress();
    state.dashboard.selectedDate=null;
    renderProgressHistory('recent');
    closeProgressLogPaste();
    if(state.loggedOnly)render();
    toast(`${logs.length} progress entr${logs.length===1?'y':'ies'} imported`);
  }catch{toast('Paste a valid progress log backup');}
}

function handleClearDataSubmit(event) {
  event.preventDefault();
  const clearLogs = $('#chkClearLogs').checked;
  const clearRoutines = $('#chkClearRoutines').checked;
  const clearSaved = $('#chkClearSaved').checked;
  const clearFuelDiary = $('#chkClearFuelDiary').checked;
  const clearMeals = $('#chkClearMeals').checked;

  if (!clearLogs && !clearRoutines && !clearSaved && !clearFuelDiary && !clearMeals) {
    return toast('Select at least one category to clear');
  }

  if (!confirm('Permanently delete the selected data? This action cannot be undone.')) {
    return;
  }

  const cleared = [];

  if (clearLogs) {
    state.progress.logs = [];
    state.dashboard.selectedDate = null;
    persistProgress();
    renderProgressHistory('recent');
    cleared.push('logs');
  }

  if (clearRoutines) {
    state.routines = [];
    state.activeRoutineId = null;
    state.routineCreating = false;
    state.routineDraftName = '';
    state.routineFilter = '';
    $('#mainRoutineSelect').value = '';
    saveRoutines();
    renderRoutineDrawer();
    cleared.push('routines');
  }

  if (clearSaved) {
    state.saved.clear();
    writeStorage(STORAGE_KEYS.saved, []);
    cleared.push('saved exercises');
  }

  if (clearFuelDiary) {
    state.fuel.history = {};
    saveFuelState();
    renderFuelDay();
    cleared.push('nutrition diary');
  }

  if (clearMeals) {
    state.fuel.foodDb = [DEFAULT_FOOD_DB[0]];
    state.fuel.selectedManageMealId = null;
    state.fuel.selectedIngredientId = 'custom';
    saveFuelState();
    renderFuelDropdowns();
    renderLikedCards();
    loadMealIntoEditor();
    cleared.push('custom meals');
  }

  render();
  closeOverlay('clearData');
  toast(`Cleared: ${cleared.join(', ')}`);
}

function updateSelectAllClearCheckbox() {
  const checkboxes = [
    $('#chkClearLogs'),
    $('#chkClearRoutines'),
    $('#chkClearSaved'),
    $('#chkClearFuelDiary'),
    $('#chkClearMeals')
  ];
  const allChecked = checkboxes.every(cb => cb.checked);
  $('#chkClearAll').checked = allChecked;
}

$('#chkClearAll')?.addEventListener('change', (e) => {
  const isChecked = e.target.checked;
  [
    $('#chkClearLogs'),
    $('#chkClearRoutines'),
    $('#chkClearSaved'),
    $('#chkClearFuelDiary'),
    $('#chkClearMeals')
  ].forEach(cb => { cb.checked = isChecked; });
});

['#chkClearLogs', '#chkClearRoutines', '#chkClearSaved', '#chkClearFuelDiary', '#chkClearMeals'].forEach(id => {
  $(id)?.addEventListener('change', updateSelectAllClearCheckbox);
});

function syncProgressDraft() {
  $('#progressSets').textContent = state.progress.draft.sets;
  $('#progressReps').textContent = state.progress.draft.reps;
  $('#progressWeight').textContent = `${state.progress.draft.weight.toLocaleString('fa-IR-u-ca-gregory')} کیلوگرم`;
  $('#progressNotes').value = state.progress.draft.notes;
}
function renderFixedExercise() {
  const exercise = EXERCISES.find((item) => item.id === state.progress.activeExerciseId);
  $('.progress-exercise-fixed').classList.toggle('empty', !exercise);
  $('#progressExerciseName').textContent = exercise ? title(exercise.name) : 'Choose an exercise from its details page';
  $('#progressExerciseMeta').textContent = exercise ? `${title(exercise.target)} · ${title(exercise.equipment)} · #${exercise.id}` : 'Open an exercise and select Log progress.';
  $('#progressSave').disabled = !exercise;
  document.querySelectorAll('.progress-step').forEach((button) => { button.disabled = !exercise; });
}
function dashboardWeekStart(offset = state.dashboard.weekOffset) {
  const today = new Date();
  today.setHours(12, 0, 0, 0);
  const start = new Date(today);
  start.setDate(today.getDate() - ((today.getDay() - state.progressPreferences.firstDay + 7) % 7) + (offset * 7));
  return start;
}
function dashboardWeekHasLogs(offset) {
  const start = dashboardWeekStart(offset);
  const end = new Date(start);
  end.setDate(start.getDate() + 6);
  return state.progress.logs.some((log) => { const date = parseLocalDate(log.date); return date >= start && date <= end; });
}
function dashboardAdjacentLoggedWeek(direction) {
  if (!state.progress.logs.length) return null;
  const earliest = state.progress.logs.reduce((minimum, log) => log.date < minimum ? log.date : minimum, state.progress.logs[0].date);
  const earliestDate = parseLocalDate(earliest);
  const earliestOffset = Math.floor((earliestDate - dashboardWeekStart(0)) / (7 * 86400000)) - 1;
  for (let offset = state.dashboard.weekOffset + direction; direction < 0 ? offset >= earliestOffset : offset <= 0; offset += direction) {
    if (dashboardWeekHasLogs(offset)) return offset;
  }
  return null;
}
function allTimeBucketStart(date, mode) {
  const start = new Date(date);
  start.setHours(12, 0, 0, 0);
  if (mode === 'day') return start;
  if (mode === 'week') start.setDate(start.getDate() - ((start.getDay() - state.progressPreferences.firstDay + 7) % 7));
  else { start.setDate(1); start.setMonth(mode === 'quarter' ? Math.floor(start.getMonth() / 3) * 3 : start.getMonth()); }
  return start;
}
function allTimeBucketLabel(date, mode, compact = false) {
  if (mode === 'day') return date.toLocaleDateString('fa-IR-u-ca-gregory', compact ? { month: 'short', day: 'numeric', year: '2-digit' } : { weekday: 'long', month: 'short', day: 'numeric', year: 'numeric' });
  if (mode === 'quarter') return `Q${Math.floor(date.getMonth() / 3) + 1}${compact ? ` ’${String(date.getFullYear()).slice(-2)}` : ` ${date.getFullYear()}`}`;
  if (mode === 'month') return date.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', year: compact ? '2-digit' : 'numeric' });
  const end = new Date(date); end.setDate(end.getDate() + 6);
  return `${date.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', day: 'numeric' })}–${end.toLocaleDateString('fa-IR-u-ca-gregory', { month: date.getMonth() === end.getMonth() ? undefined : 'short', day: 'numeric' })}`;
}
function renderDashboardAllTimeChart(logs) {
  const chart = $('#dashboardAllTimeChart');
  if (!logs.length) { chart.innerHTML = '<div class="all-time-chart-empty">No training data yet</div>'; return; }
  const exactDates = logs.map((log) => parseLocalDate(log.date)).sort((left, right) => left - right);
  const exactFirst = exactDates[0], exactLast = exactDates[exactDates.length - 1];
  const mode = 'day';
  const buckets = new Map();
  logs.forEach((log) => {
    const start = allTimeBucketStart(parseLocalDate(log.date), mode);
    const key = localDateValue(start);
    if (!buckets.has(key)) buckets.set(key, { date: start, sets: 0, volume: 0, dates: new Set(), exercises: new Set() });
    const bucket = buckets.get(key);
    bucket.sets += log.sets;
    bucket.volume += log.sets * log.reps * (Number(log.weight) || 0);
    bucket.dates.add(log.date);
    bucket.exercises.add(log.exerciseId);
  });
  const series = [...buckets.values()].sort((left, right) => left.date - right.date).map((bucket) => ({ date: bucket.date, sets: bucket.sets, volume: bucket.volume, exercises: bucket.exercises.size }));
  const width = 320, height = 100, left = 36, right = 312, top = 4, baseline = 96;
  const maximum = Math.max(1, ...series.map((item) => item.volume)), half = maximum / 2;
  const step = series.length > 1 ? (right - left) / (series.length - 1) : 0;
  const barWidth = Math.max(1.5, Math.min(18, (right - left) / Math.max(series.length, 1) * .58));
  const points = series.map((item, index) => {
    const x = series.length === 1 ? (left + right) / 2 : left + index * step;
    const y = baseline - (item.volume / maximum) * (baseline - top);
    return { ...item, x, y };
  });
  const bars = points.map((point, index) => `<g class="chart-hit" data-index="${index}" tabindex="0" role="button" aria-label="${esc(allTimeBucketLabel(point.date, mode))}: ${point.volume.toLocaleString()} kilograms of volume"><rect class="chart-bar" x="${(point.x - barWidth / 2).toFixed(2)}" y="${Math.min(point.y, baseline - 2).toFixed(2)}" width="${barWidth.toFixed(2)}" height="${Math.max(2, baseline - point.y).toFixed(2)}" rx="2"/><rect class="chart-hitbox" x="${(point.x - Math.max(barWidth, step || 32) / 2).toFixed(2)}" y="${top}" width="${Math.max(barWidth, step || 32).toFixed(2)}" height="${baseline - top}"/></g>`).join('');
  const trendPoints = points.map((point, index) => {
    const values = series.slice(Math.max(0, index - 3), index + 1);
    const average = values.reduce((sum, item) => sum + item.volume, 0) / values.length;
    return { x: point.x, y: baseline - (average / maximum) * (baseline - top) };
  });
  const trendLine = trendPoints.map((point, index) => `${index ? 'L' : 'M'}${point.x.toFixed(2)} ${point.y.toFixed(2)}`).join(' ');
  const currentFour = series.slice(-4).reduce((sum, item) => sum + item.volume, 0), previousFour = series.slice(-8, -4).reduce((sum, item) => sum + item.volume, 0);
  const trendChange = previousFour ? Math.round(((currentFour - previousFour) / previousFour) * 100) : null;
  const trendText = series.length < 5 ? 'Building trend' : trendChange === null ? 'New activity' : trendChange > 0 ? `Last 4 workouts: ↑ ${trendChange}%` : trendChange < 0 ? `Last 4 workouts: ↓ ${Math.abs(trendChange)}%` : 'Last 4 workouts: No change';
  const trendType = trendChange > 0 ? 'up' : trendChange < 0 ? 'down' : 'same';
  const endpointOptions = { month: 'short', day: 'numeric', year: exactFirst.getFullYear() === exactLast.getFullYear() ? undefined : 'numeric' };
  const firstLabel = exactFirst.toLocaleDateString('fa-IR-u-ca-gregory', endpointOptions), lastLabel = exactLast.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', day: 'numeric', year: exactFirst.getFullYear() === exactLast.getFullYear() ? undefined : 'numeric' });
  const labelIndices = [...new Set([0, Math.round((series.length - 1) / 3), Math.round(((series.length - 1) * 2) / 3), series.length - 1])];
  const xLabels = labelIndices.map((index) => { const point = points[index], label = index === 0 ? firstLabel : index === series.length - 1 ? lastLabel : allTimeBucketLabel(point.date, mode, true), endpointClass = index === 0 ? ' chart-x-start' : index === series.length - 1 ? ' chart-x-end' : ''; return `<span class="chart-label chart-x-label${endpointClass}" style="left:${((point.x / width) * 100).toFixed(2)}%">${esc(label)}</span>`; }).join('');
  chart.innerHTML = `<span class="chart-trend" data-trend="${trendType}">${esc(trendText)}</span><span class="chart-label chart-y-label chart-y-max">${maximum.toLocaleString()}</span><span class="chart-label chart-y-label chart-y-half">${Number.isInteger(half) ? half.toLocaleString() : half.toFixed(1)}</span><span class="chart-label chart-y-label chart-y-zero">0</span><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="All-time workout volume"><line class="chart-grid" x1="${left}" y1="${top}" x2="${right}" y2="${top}"/><line class="chart-grid" x1="${left}" y1="${(top + baseline) / 2}" x2="${right}" y2="${(top + baseline) / 2}"/><line class="chart-grid" x1="${left}" y1="${baseline}" x2="${right}" y2="${baseline}"/>${bars}<path class="chart-trend-line" d="${trendLine}"/></svg>${xLabels}<div class="chart-tooltip" role="status" hidden></div>`;
  const tooltip = chart.querySelector('.chart-tooltip');
  const showTooltip = (index) => {
    const point = points[index], active = chart.querySelector(`.chart-hit[data-index="${index}"]`), alreadyActive = active.classList.contains('active');
    chart.querySelectorAll('.chart-hit').forEach((item) => item.classList.remove('active'));
    if (alreadyActive) { tooltip.hidden = true; return; }
    active.classList.add('active');
    tooltip.innerHTML = `<strong>${esc(allTimeBucketLabel(point.date, mode))}</strong><span>${point.volume.toLocaleString()} kg volume · ${point.sets} set${point.sets === 1 ? '' : 's'} · ${point.exercises} exercise${point.exercises === 1 ? '' : 's'}</span>`;
    tooltip.style.left = `${Math.max(22, Math.min(78, (point.x / width) * 100))}%`;
    tooltip.style.top = `${Math.max(24, Math.min(76, 18 + point.y - 42))}px`;
    tooltip.hidden = false;
  };
  chart.querySelectorAll('.chart-hit').forEach((item) => { item.addEventListener('click', () => showTooltip(Number(item.dataset.index))); item.addEventListener('keydown', (event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); showTooltip(Number(item.dataset.index)); } }); });
}
function renderProgressDashboard() {
  const logs = state.progress.logs;
  const allTime = state.dashboard.scope === 'all';
  const weekStart = dashboardWeekStart();
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
  const weekLogs = logs.filter((log) => { const date = parseLocalDate(log.date); return date >= weekStart && date <= weekEnd; });
  const scopedLogs = state.dashboard.selectedDate ? logs.filter((log) => log.date === state.dashboard.selectedDate) : logs;
  const balanceLabel = $('#dashboardBalanceLabel');
  balanceLabel.textContent = state.dashboard.selectedDate ? parseLocalDate(state.dashboard.selectedDate).toLocaleDateString('fa-IR-u-ca-gregory', { weekday: 'long', month: 'short', day: 'numeric' }) : allTime ? 'All time' : 'Weekly';

  const days = Array.from({ length: 7 }, (_, index) => {
    const date = new Date(weekStart);
    date.setDate(weekStart.getDate() + index);
    const key = localDateValue(date);
    const dayLogs = logs.filter((log) => log.date === key);
    return { key, label: date.toLocaleString('fa-IR-u-ca-gregory', { weekday: 'narrow' }), longLabel: date.toLocaleDateString('fa-IR-u-ca-gregory', { weekday: 'long', month: 'short', day: 'numeric' }), sets: dayLogs.reduce((sum, log) => sum + log.sets, 0), entries: dayLogs.length };
  });
  const maxSets = Math.max(1, ...days.map((day) => day.sets));
  const weekSets = days.reduce((sum, day) => sum + day.sets, 0);
  const weekSessions = new Set(weekLogs.map((log) => log.date)).size;
  const weekExercises = new Set(weekLogs.map((log) => log.exerciseId)).size;
  const currentWeek = state.dashboard.weekOffset === 0;
  $('#dashboardWeekLabel').textContent = allTime ? 'All time' : currentWeek ? 'This week' : 'Selected week';
  if (allTime && logs.length) {
    const sortedDates = logs.map((log) => parseLocalDate(log.date)).sort((left, right) => left - right);
    const firstDate = sortedDates[0], lastDate = sortedDates[sortedDates.length - 1];
    $('#dashboardWeekRange').textContent = `${firstDate.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', day: 'numeric', year: firstDate.getFullYear() === lastDate.getFullYear() ? undefined : 'numeric' })} – ${lastDate.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', day: 'numeric', year: 'numeric' })}`;
  } else $('#dashboardWeekRange').textContent = allTime ? 'Training sets' : `${weekStart.toLocaleDateString('fa-IR-u-ca-gregory', { month: 'short', day: 'numeric' })} – ${weekEnd.toLocaleDateString('fa-IR-u-ca-gregory', { month: weekStart.getMonth() === weekEnd.getMonth() ? undefined : 'short', day: 'numeric' })}`;
  const summary = $('#dashboardWeekSummary');
  if (allTime) {
    const allSets = logs.reduce((sum, log) => sum + log.sets, 0);
    const allSessions = new Set(logs.map((log) => log.date)).size;
    const allExercises = new Set(logs.map((log) => log.exerciseId)).size;
    summary.textContent = `${allSessions.toLocaleString()} session${allSessions === 1 ? '' : 's'} · ${allSets.toLocaleString()} set${allSets === 1 ? '' : 's'} · ${allExercises.toLocaleString()} exercise${allExercises === 1 ? '' : 's'}`;
  } else if (state.dashboard.selectedDate) {
    const daySets = scopedLogs.reduce((sum, log) => sum + log.sets, 0);
    const dayExercises = new Set(scopedLogs.map((log) => log.exerciseId)).size;
    const dayReps = scopedLogs.reduce((sum, log) => sum + (log.sets * log.reps), 0);
    summary.textContent = `${dayExercises.toLocaleString()} exercise${dayExercises === 1 ? '' : 's'} · ${daySets.toLocaleString()} set${daySets === 1 ? '' : 's'} · ${dayReps.toLocaleString()} reps`;
  } else {
    summary.textContent = `${weekSessions.toLocaleString()} session${weekSessions === 1 ? '' : 's'} · ${weekSets.toLocaleString()} set${weekSets === 1 ? '' : 's'} · ${weekExercises.toLocaleString()} exercise${weekExercises === 1 ? '' : 's'}`;
  }
  const previousLoggedWeek = dashboardAdjacentLoggedWeek(-1);
  const nextLoggedWeek = dashboardAdjacentLoggedWeek(1);
  $('#dashboardPreviousWeek').disabled = previousLoggedWeek === null;
  $('#dashboardPreviousWeek').dataset.weekOffset = previousLoggedWeek ?? '';
  $('#dashboardNextWeek').disabled = nextLoggedWeek === null;
  $('#dashboardNextWeek').dataset.weekOffset = nextLoggedWeek ?? '';
  $('#dashboardResetWeek').disabled = currentWeek && !state.dashboard.selectedDate;
  $('#dashboardWeeklyBars').innerHTML = days.map((day) => `<button class="weekly-bar-item" type="button" data-date="${day.key}" aria-label="${esc(day.longLabel)}: ${day.sets} sets in ${day.entries} entries" aria-pressed="${state.dashboard.selectedDate === day.key}"${day.entries ? '' : ' disabled'}><span>${day.sets || ''}</span><div class="weekly-bar-track"><i style="height:${day.sets ? Math.max(10, Math.round((day.sets / maxSets) * 100)) : 3}%"></i></div><small>${esc(day.label)}</small></button>`).join('');
  const weekNavigation = $('.dashboard-week-nav');
  $('.dashboard-week-card').classList.toggle('all-time-view', allTime);
  weekNavigation.hidden = allTime;
  weekNavigation.inert = allTime;
  weekNavigation.setAttribute('aria-hidden', String(allTime));
  $('#dashboardWeeklyBars').hidden = allTime;
  $('#dashboardAllTimeChart').hidden = !allTime;
  const scopeToggle = $('#dashboardScopeToggle');
  scopeToggle.querySelector('use').setAttribute('href', allTime ? '#icon-calendar' : '#icon-progress');
  scopeToggle.setAttribute('aria-label', allTime ? 'Show weekly view' : 'Show all-time chart');
  scopeToggle.setAttribute('aria-pressed', String(allTime));
  if (allTime) renderDashboardAllTimeChart(logs);

  const balanceLogs = allTime ? logs : state.dashboard.selectedDate ? scopedLogs : weekLogs;
  const byCategory = new Map();
  balanceLogs.forEach((log) => {
    const exercise = EXERCISES.find((item) => item.id === log.exerciseId);
    const category = exercise?.category || 'Other';
    if (!byCategory.has(category)) byCategory.set(category, { sets: 0, exerciseIds: new Set() });
    const summary = byCategory.get(category);
    summary.sets += log.sets;
    summary.exerciseIds.add(log.exerciseId);
  });
  const categories = [...byCategory.entries()].sort((left, right) => right[1].sets - left[1].sets).slice(0, 5);
  const categoryMax = Math.max(1, ...categories.map(([, summary]) => summary.sets));
  $('#dashboardMuscleSummary').textContent = categories.length ? `${byCategory.size} group${byCategory.size === 1 ? '' : 's'}` : 'No data yet';
  $('#dashboardMuscleBreakdown').innerHTML = categories.map(([category, summary]) => { const exerciseCount = summary.exerciseIds.size; return `<div class="muscle-row"><div><strong>${esc(title(category))}</strong><span>${summary.sets.toLocaleString()} set${summary.sets === 1 ? '' : 's'}, ${exerciseCount.toLocaleString()} exercise${exerciseCount === 1 ? '' : 's'}</span></div><div class="track" style="height:7px"><i style="width:${Math.round((summary.sets / categoryMax) * 100)}%; background:var(--accent)"></i></div></div>`; }).join('');
  $('#dashboardEmpty').hidden = Boolean(logs.length);
}
function renderProgressHistory() {
  const activeExercise = EXERCISES.find((exercise) => exercise.id === state.progress.activeExerciseId);
  const allTime = state.dashboard.scope === 'all';
  const weekStart = dashboardWeekStart();
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekStart.getDate() + 6);
  const selectedDayView = !activeExercise && Boolean(state.dashboard.selectedDate);
  const visibleLogs = [...state.progress.logs].filter((log) => {
    if (activeExercise) return log.exerciseId === activeExercise.id;
    if (state.dashboard.selectedDate) return log.date === state.dashboard.selectedDate;
    if (allTime) return true;
    const date = parseLocalDate(log.date);
    return date >= weekStart && date <= weekEnd;
  }).sort((left, right) => right.date.localeCompare(left.date) || right.createdAt - left.createdAt);
  const context = $('#progressHistoryContext');
  $('#progressHistoryHead').hidden = !activeExercise;
  context.textContent = activeExercise ? title(activeExercise.name) : '';
  $('#progressHistory').innerHTML = visibleLogs.length ? visibleLogs.map((log) => {
    const exercise = EXERCISES.find((item) => item.id === log.exerciseId);
    if (!exercise) return '';
    const date = parseLocalDate(log.date);
    const entryVisual = selectedDayView ? `<div class="progress-entry-date progress-entry-thumbnail" aria-hidden="true">${icon('movement')}<img src="${esc(exercise.image)}" alt=""></div>` : `<div class="progress-entry-date"><b>${date.getDate()}</b><span>${date.toLocaleString('fa-IR-u-ca-gregory', { month: 'short' })}</span></div>`;
    return `<article class="progress-entry" data-progress-id="${esc(log.id)}" data-exercise-id="${esc(exercise.id)}" role="button" tabindex="0" aria-label="Open ${esc(exercise.name)} details">${entryVisual}<div class="progress-entry-copy"><strong>${esc(title(exercise.name))}</strong><span>${esc(formatProgress(log))}</span>${log.notes ? `<small>${esc(log.notes)}</small>` : ''}</div><button class="entry-delete" type="button" aria-label="Delete ${esc(exercise.name)} progress entry">${icon('trash')}</button></article>`;
  }).join('') : `<div class="feature-empty">${activeExercise ? 'هیچ سابقه‌ای برای این حرکت ثبت نشده است.' : state.dashboard.selectedDate ? 'هیچ سابقه‌ای برای این روز ثبت نشده است.' : allTime ? 'هنوز هیچ سابقه‌ای ثبت نشده است.' : 'هیچ سابقه‌ای برای این هفته ثبت نشده است.'}</div>`;
  $('#progressHistory').querySelectorAll('.progress-entry-thumbnail img').forEach((image) => image.addEventListener('error', () => image.classList.add('failed'), { once: true }));
  renderProgressDashboard();
}
function openProgress(exerciseId = '', returnFocus = document.activeElement) {
  const validExercise = exerciseId && VALID_EXERCISE_IDS.has(exerciseId);
  state.progress.activeExerciseId = validExercise ? exerciseId : null;
  state.progress.popup = Boolean(validExercise);
  $('#progressEyebrow').textContent = validExercise ? 'New entry' : 'Training history';
  $('#progressTitle').textContent = validExercise ? 'Log progress' : 'Dashboard';
  $('#progressDashboard').hidden = Boolean(validExercise);
  $('#progressForm').hidden = !validExercise;
  $('#progressSettingsBtn').hidden = Boolean(validExercise);
  $('#progressSubtitle').textContent = validExercise ? 'Add a training entry for this exercise.' : 'Your training dashboard and recent activity.';
  closeProgressSettings();
  resetProgressDraft();
  renderFixedExercise();
  syncProgressDraft();
  setProgressDateValue(localDateValue());
  renderProgressHistory(validExercise ? exerciseId : 'recent');
  openOverlay('progress', returnFocus);
  if (mobileFiltersQuery.matches) syncMobileTabs();
  syncProgressPopupHeight();
}
function syncProgressPopupHeight() {
  const panel = $('#progressBackdrop .feature-panel');
  if (!panel) return;
  const form = $('#progressForm');
  if (mobileFiltersQuery.matches && state.overlay.active === 'progress' && state.progress.popup && form && !form.hidden) {
    const header = panel.querySelector('.feature-header');
    if (header) panel.style.height = `${Math.ceil(header.offsetHeight + form.offsetHeight + 8 + 120)}px`;
  } else {
    panel.style.height = '';
  }
}
function closeProgress(restoreFocus = true) {
  const wasPopup = Boolean(state.progress.popup);
  closeProgressDatePicker(false);
  state.progress.popup = false;
  syncProgressPopupHeight();
  closeOverlay('progress', restoreFocus);
  if (mobileFiltersQuery.matches && wasPopup) {
    if (state.mobileTab === 'dashboard') prepareDashboardTab();
    syncMobileTabs();
  }
}
function saveProgressLog(event) {
  event.preventDefault();
  const exercise = EXERCISES.find((item) => item.id === state.progress.activeExerciseId);
  const date = $('#progressDate').value;
  if (!exercise) return toast('Open an exercise and select Log progress');
  if (!date) return toast('Choose a date');
  const timestamp = Date.now();
  const log = {
    id: String(timestamp),
    exerciseId: exercise.id,
    date,
    sets: state.progress.draft.sets,
    reps: state.progress.draft.reps,
    weight: state.progress.draft.weight > 0 ? state.progress.draft.weight : null,
    notes: state.progress.draft.notes.trim().slice(0, LIMITS.notes),
    createdAt: timestamp,
  };
  state.progress.logs.push(log);
  persistProgress();
  state.progress.draft.notes = '';
  $('#progressNotes').value = '';
  renderProgressHistory(exercise.id);
  updateModalProgress(exercise.id);
  const modalLike = $('#modalLikeExercise');
  modalLike.classList.toggle('saved', state.saved.has(exercise.id));
  modalLike.setAttribute('aria-pressed', String(state.saved.has(exercise.id)));
  modalLike.setAttribute('aria-label', `${state.saved.has(exercise.id) ? 'Remove from' : 'Add to'} saved exercises`);
  if (state.loggedOnly || (state.routineFilter && state.view === 'list')) render();
  toast('Progress entry saved');
}

function updateFilterSemantics() {
  const filters = $('#filters');
  if (mobileFiltersQuery.matches) {
    filters.setAttribute('role', 'dialog');
    filters.setAttribute('aria-modal', 'true');
    filters.setAttribute('aria-hidden', String(!filters.classList.contains('open')));
  } else {
    filters.removeAttribute('role');
    filters.removeAttribute('aria-modal');
    filters.removeAttribute('aria-hidden');
  }
}
function openFilters(returnFocus = document.activeElement) {
  if (!mobileFiltersQuery.matches) return;
  openOverlay('filters', returnFocus);
}
function closeFilters(restoreFocus = true) {
  closeOverlay('filters', restoreFocus);
}
function prepareDashboardTab() {
  state.progress.activeExerciseId = null;
  state.progress.popup = false;
  syncProgressPopupHeight();
  $('#progressEyebrow').textContent = 'Training history';
  $('#progressTitle').textContent = 'Dashboard';
  $('#progressDashboard').hidden = false;
  $('#progressForm').hidden = true;
  $('#progressSettingsBtn').hidden = false;
  $('#progressSubtitle').textContent = 'Your training dashboard and recent activity.';
  closeProgressSettings();
  resetProgressDraft();
  renderFixedExercise();
  syncProgressDraft();
  setProgressDateValue(localDateValue());
  renderProgressHistory('recent');
}
function syncMobileTabs() {
  const mobile = mobileFiltersQuery.matches;
  const tab = mobile ? state.mobileTab : 'workout';
  const main = $('#workoutTabPanel');
  const routine = $('#routineDrawer');
  const dashboard = $('#progressBackdrop');
  const fuel = $('#fuelBackdrop');
  const meals = $('#fuelSettingsBackdrop');
  $('#mobileProgressBtn').setAttribute('aria-selected', String(tab === 'dashboard'));
  $('#mobileWorkoutBtn').setAttribute('aria-selected', String(tab === 'workout'));
  $('#mobileFuelBtn').setAttribute('aria-selected', String(tab === 'fuel'));
  routine.classList.toggle('mobile-tab-active', mobile && tab === 'routines');
  const progressPopup = mobile && state.overlay.active === 'progress' && state.progress.popup;
  dashboard.classList.toggle('mobile-tab-active', mobile && tab === 'dashboard' && !progressPopup);
  fuel.classList.toggle('mobile-tab-active', mobile && tab === 'fuel');
  meals.classList.toggle('mobile-tab-active', mobile && tab === 'meals');
  if (mobile) {
    document.body.dataset.mobileTab = tab;
    main.setAttribute('role', 'tabpanel');
    main.setAttribute('aria-labelledby', 'mobileWorkoutBtn');
    main.setAttribute('aria-hidden', String(tab !== 'workout'));
    routine.setAttribute('role', 'tabpanel');
    routine.removeAttribute('aria-modal');
    routine.setAttribute('aria-labelledby', 'routineTitle');
    routine.setAttribute('aria-hidden', String(tab !== 'routines'));
    fuel.setAttribute('role', 'tabpanel');
    fuel.removeAttribute('aria-modal');
    fuel.setAttribute('aria-labelledby', 'mobileFuelBtn');
    fuel.setAttribute('aria-hidden', String(tab !== 'fuel'));
    meals.setAttribute('role', 'tabpanel');
    meals.removeAttribute('aria-modal');
    meals.setAttribute('aria-labelledby', 'fuelSettingsTitle');
    meals.setAttribute('aria-hidden', String(tab !== 'meals'));
    if (progressPopup) {
      dashboard.setAttribute('role', 'dialog');
      dashboard.setAttribute('aria-modal', 'true');
      dashboard.setAttribute('aria-labelledby', 'progressTitle');
      dashboard.setAttribute('aria-hidden', 'false');
    } else {
      dashboard.setAttribute('role', 'tabpanel');
      dashboard.removeAttribute('aria-modal');
      dashboard.setAttribute('aria-labelledby', 'mobileProgressBtn');
      dashboard.setAttribute('aria-hidden', String(tab !== 'dashboard'));
    }
  } else {
    delete document.body.dataset.mobileTab;
    main.removeAttribute('role');
    main.removeAttribute('aria-labelledby');
    main.removeAttribute('aria-hidden');
    routine.setAttribute('role', 'dialog');
    routine.setAttribute('aria-modal', 'true');
    routine.setAttribute('aria-labelledby', 'routineTitle');
    routine.setAttribute('aria-hidden', String(!routine.classList.contains('open')));
    dashboard.setAttribute('role', 'dialog');
    dashboard.setAttribute('aria-modal', 'true');
    dashboard.setAttribute('aria-labelledby', 'progressTitle');
    dashboard.setAttribute('aria-hidden', String(!dashboard.classList.contains('open')));
    fuel.setAttribute('role', 'dialog');
    fuel.setAttribute('aria-modal', 'true');
    fuel.setAttribute('aria-labelledby', 'fuelTitle');
    fuel.setAttribute('aria-hidden', String(!fuel.classList.contains('open')));
    meals.setAttribute('role', 'dialog');
    meals.setAttribute('aria-modal', 'true');
    meals.setAttribute('aria-labelledby', 'fuelSettingsTitle');
    meals.setAttribute('aria-hidden', String(!meals.classList.contains('open')));
  }
  syncPageState();
}
function mobileTabPanel(tab) {
  if (tab === 'dashboard') return $('#progressBackdrop .feature-panel');
  if (tab === 'fuel') return $('#fuelBackdrop .feature-panel');
  if (tab === 'routines') return $('#routineDrawer');
  if (tab === 'meals') return $('#fuelSettingsBackdrop .fuel-drawer');
  return $('#workoutTabPanel');
}
function setMobileTab(tab) {
  const tabs = ['dashboard', 'workout', 'routines', 'fuel', 'meals'];
  if (!mobileFiltersQuery.matches || !tabs.includes(tab)) return;
  if (state.mobileTab === 'meals' && tab !== 'meals' && state.fuel.selectedManageMealId) {
    toast('Please save your meal before closing');
    return;
  }
  if (state.mobileTab === 'dashboard' && tab !== 'dashboard') state.dashboard.selectedDate = null;
  if (state.overlay.active) closeActiveOverlay(false);
  if (state.mobileTab === tab) return;

  state.mobileTab = tab;
  pushTabHistory(tab);
  if (tab === 'dashboard') prepareDashboardTab();
  if (tab === 'fuel') renderAll();
  if (tab === 'routines') renderRoutineDrawer();
  if (tab === 'meals') { renderNonNativeManageDropdown(); loadMealIntoEditor(); }
  syncMobileTabs();
}
function syncResponsiveView() {
  const nextView = narrowViewQuery.matches ? 'list' : state.preferredView;
  if (state.view === nextView) return;
  state.view = nextView;
  render();
}

let searchDebounce;
$('#search').addEventListener('input', (event) => {
  clearTimeout(searchDebounce);
  searchDebounce = setTimeout(() => { state.search = event.target.value; state.limit = DEFAULTS.pageSize; render(); }, 120);
});
[['#categoryFilter', 'category'], ['#targetFilter', 'target'], ['#equipmentFilter', 'equipment']].forEach(([selector, key]) => {
  $(selector).addEventListener('change', (event) => { state[key] = event.target.value; state.limit = DEFAULTS.pageSize; render(); });
});
[['#savedOnly', 'savedOnly'], ['#bodyWeightOnly', 'bodyWeightOnly'], ['#loggedOnly', 'loggedOnly']].forEach(([selector, key]) => {
  $(selector).addEventListener('click', () => { state[key] = !state[key]; state.limit = DEFAULTS.pageSize; render(); });
});
$('#sortBy').addEventListener('change', (event) => { state.sort = event.target.value; state.limit = DEFAULTS.pageSize; render(); });
$('#clearFilters').addEventListener('click', resetFilters);
$('#loadMore').addEventListener('click', () => { state.limit += DEFAULTS.pageSize; render(); });
$('#activeFilters').addEventListener('click', (event) => {
  const button = event.target.closest('[data-clear]');
  if (!button) return;
  const key = button.dataset.clear;
  if (key === 'search') { state.search = ''; $('#search').value = ''; }
  else if (['savedOnly', 'bodyWeightOnly', 'loggedOnly'].includes(key)) { state[key] = false; }
  else if (key === 'routineFilter') { state.routineFilter = ''; $('#mainRoutineSelect').value = ''; syncRoutineSort(); }
  else { state[key] = ''; $(`#${key}Filter`).value = ''; }
  render();
});
$('#grid').addEventListener('click', (event) => {
  const card = event.target.closest('.card');
  if (!card) return;
  const exercise = EXERCISES.find((item) => item.id === card.dataset.id);
  const addButton = event.target.closest('.add-routine');
  const checkButton = event.target.closest('.routine-check');
  const progressButton = event.target.closest('.card-progress');
  const saveButton = event.target.closest('.save-button');
  if (addButton) addToRoutine(exercise.id);
  else if (checkButton) {
    const routine = currentRoutine();
    if (!routine || !routine.items.some(item => item.exerciseId === exercise.id)) return;
    if (!confirm(`Remove "${exercise.name}" from "${routine.name}" routine?`)) return;
    routine.items = routine.items.filter(item => item.exerciseId !== exercise.id);
    saveRoutines();
    renderRoutineDrawer();
    render();
    toast(`Removed from ${routine.name} routine`);
  } else if (progressButton) openProgress(exercise.id, progressButton);
  else if (saveButton) {
    const saved = setSavedExercise(exercise.id);
    if (state.savedOnly) render();
    else {
      saveButton.classList.toggle('saved', saved);
      saveButton.setAttribute('aria-pressed', String(saved));
      saveButton.setAttribute('aria-label', `${saved ? 'Remove from' : 'Add to'} saved exercises`);
      toast(saved ? 'Exercise saved' : 'Removed from saved');
    }
  } else openModal(exercise, card);
});
$('#grid').addEventListener('keydown', (event) => {
  const card = event.target.closest('.card');
  if (!card || event.target.closest('button') || !['Enter', ' '].includes(event.key)) return;
  event.preventDefault();
  openModal(EXERCISES.find((exercise) => exercise.id === card.dataset.id), card);
});
$('#gridView').addEventListener('click', () => { state.preferredView = 'grid'; state.view = narrowViewQuery.matches ? 'list' : 'grid'; try { localStorage.setItem(STORAGE_KEYS.view, 'grid'); } catch {} render(); });
$('#listView').addEventListener('click', () => { state.preferredView = 'list'; state.view = 'list'; try { localStorage.setItem(STORAGE_KEYS.view, 'list'); } catch {} render(); });

$('#mobileWorkoutBtn').addEventListener('click', (event) => {
  if (state.overlay.active === 'progress' && state.progress.popup) {
    closeProgress(false);
    if (state.mobileTab !== 'workout') setMobileTab('workout');
    event.currentTarget.focus({ preventScroll: true });
    return;
  }
  if (state.overlay.active === 'modal') {
    closeModal(false);
    setMobileTab('workout');
    event.currentTarget.focus({ preventScroll: true });
    return;
  }
  if (state.mobileTab !== 'workout') setMobileTab('workout');
  else if (state.overlay.active === 'filters') closeFilters();
  else openFilters(event.currentTarget);
});
$('#drawerBackdrop').addEventListener('click', () => closeFilters());
mobileFiltersQuery.addEventListener('change', () => {
  if (!mobileFiltersQuery.matches) {
    if (state.overlay.active === 'filters') closeFilters(false);
    state.mobileTab = 'workout';
  }
  updateFilterSemantics();
  syncMobileTabs();
  syncSortPlacement();
});
phoneViewQuery.addEventListener('change', syncSortPlacement);
narrowViewQuery.addEventListener('change', syncResponsiveView);
window.addEventListener('resize', syncProgressPopupHeight);

$('#routineClose').addEventListener('click', () => mobileFiltersQuery.matches && state.mobileTab === 'routines' ? setMobileTab('workout') : closeOverlay('routine'));
$('#routineBackdrop').addEventListener('click', () => closeOverlay('routine'));
$('#routineNewToggle').addEventListener('click', () => {
  if (state.routineCreating) cancelNewRoutine();
  else if (currentRoutine()) saveRoutineEditor();
  else beginNewRoutine();
});
$('#routineSelectorButton').addEventListener('click', (event) => {
  const menu = $('#routineMenu');
  const willOpen = menu.hidden;
  closeAllCustomMenus(willOpen ? menu : null);
  menu.hidden = !willOpen;
  event.currentTarget.setAttribute('aria-expanded', String(willOpen));
});
$('#routineMenu').addEventListener('click', (event) => {
  const option = event.target.closest('[data-edit-routine]');
  if (!option) return;
  beginRoutineEdit(option.dataset.editRoutine);
});
$('#routineEditName').addEventListener('input', (event) => { state.routineDraftName = event.currentTarget.value; });
$('#routineEditName').addEventListener('keydown', (event) => {
  if (event.key === 'Enter') { event.preventDefault(); saveRoutineEditor(); }
});
$('#mainRoutineSelect').addEventListener('change', (event) => { state.routineFilter = event.target.value; state.limit = DEFAULTS.pageSize; syncRoutineSort(true); render(); });
$('#likeRoutine').addEventListener('click',()=>{
  const routine=currentRoutine();
  if(!routine)return;
  if(!routine.liked&&state.routines.filter(item=>item.liked).length>=6)return toast('You can like up to 6 routines');
  routine.liked=!routine.liked;
  saveRoutines();
  renderRoutineDrawer();
  toast(routine.liked?'Routine liked':'Routine unliked');
});
$('#likedRoutineFilters').addEventListener('click',event=>{
  const button=event.target.closest('[data-routine-id]');
  if(!button)return;
  state.routineFilter=state.routineFilter===button.dataset.routineId?'':button.dataset.routineId;
  $('#mainRoutineSelect').value=state.routineFilter;
  state.limit=DEFAULTS.pageSize;
  syncRoutineSort(Boolean(state.routineFilter));
  renderLikedRoutineFilters();
  render();
});
$('#moreRoutinesSelect').addEventListener('change',event=>{
  state.routineFilter=event.target.value;
  $('#mainRoutineSelect').value=state.routineFilter;
  state.limit=DEFAULTS.pageSize;
  syncRoutineSort(Boolean(state.routineFilter));
  render();
});
$('#deleteRoutine').addEventListener('click', () => {
  if (state.routineCreating) return saveRoutineEditor();
  const routine = currentRoutine();
  if (!routine || !confirm(`Delete "${routine.name}"?`)) return;
  state.routines = state.routines.filter((item) => item.id !== routine.id);
  state.activeRoutineId = null;
  state.routineCreating = false;
  state.routineDraftName = '';
  if (state.routineFilter === routine.id) state.routineFilter = '';
  saveRoutines(); renderRoutineDrawer(); render(); toast('Routine deleted');
});
