/* =========================================================
   FUEL — Nutrition Module Script
   ========================================================= */

function saveFuelState() {
  writeStorage(STORAGE_KEYS.fuel, state.fuel);
}

function renderFuelDropdowns() {
  renderNonNativeIngredientDropdown();
  renderNonNativeManageDropdown();
}

function ensureDateRecord(dateKey) {
  if (!state.fuel.history[dateKey]) {
    state.fuel.history[dateKey] = { water: 0, meals: [] };
  }
}

function setSelectByFloat(elementId, targetVal) {
  const sel = document.getElementById(elementId);
  if (!sel) return;
  const targetNum = parseFloat(targetVal);
  for (let i = 0; i < sel.options.length; i++) {
    if (Math.abs(parseFloat(sel.options[i].value) - targetNum) < 0.001) {
      sel.selectedIndex = i;
      syncCustomSelect(sel);
      return;
    }
  }
}

function openLogMealForNew() {
  resetMealSelection();
  openOverlay('logMeal');
}

function changeDate(delta) {
  const today = localDateValue();
  if (delta > 0 && state.fuelSelectedDate >= today) return;

  const d = parseLocalDate(state.fuelSelectedDate);
  d.setDate(d.getDate() + delta);
  state.fuelSelectedDate = localDateValue(d);
  renderFuelDay();
}

function goToToday() {
  state.fuelSelectedDate = localDateValue();
  renderFuelDay();
  toast('Switched to today');
}

document.getElementById('bodyMetricsModal').addEventListener('click', (e) => {
  if (e.target.id === 'bodyMetricsModal') closeOverlay('bodyMetrics');
});
document.getElementById('fuelLogMealModal').addEventListener('click', (e) => {
  if (e.target.id === 'fuelLogMealModal') closeOverlay('logMeal');
});
document.getElementById('fuelSettingsBackdrop').addEventListener('click', (e) => {
  if (e.target.id === 'fuelSettingsBackdrop') closeOverlay('mealManager');
});
document.getElementById('clearDataModal').addEventListener('click', (e) => {
  if (e.target.id === 'clearDataModal') closeOverlay('clearData');
});

function getSortedFoodDb(includeCustom = true) {
  const list = includeCustom ? [...state.fuel.foodDb] : state.fuel.foodDb.filter(i => i.id !== 'custom');
  const customItem = list.find(i => i.id === 'custom');
  const otherItems = list.filter(i => i.id !== 'custom');

  const liked = otherItems.filter(i => i.liked).sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));
  const unliked = otherItems.filter(i => !i.liked).sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }));

  return customItem ? [customItem, ...liked, ...unliked] : [...liked, ...unliked];
}

function toggleIngredientDropdown() {
  const menu = document.getElementById('menuCustomIngredient');
  const btn = document.getElementById('btnCustomIngredientSelect');
  const willOpen = menu.hidden;
  closeAllCustomMenus(willOpen ? menu : null);
  menu.hidden = !willOpen;
  btn.setAttribute('aria-expanded', String(willOpen));
}

function renderNonNativeIngredientDropdown() {
  const menu = document.getElementById('menuCustomIngredient');
  const sorted = getSortedFoodDb(true);
  const selectedItem = state.fuel.foodDb.find(i => i.id === state.fuel.selectedIngredientId) || sorted[0];

  document.getElementById('lblCustomIngredient').textContent = `${selectedItem.liked ? '♥ ' : ''}${selectedItem.name}`;

  menu.innerHTML = sorted.map(ing => `
    <button type="button" role="option" data-ingredient-id="${esc(ing.id)}" aria-selected="${String(ing.id === selectedItem.id)}">${ing.liked ? '♥ ' : ''}${esc(ing.name)}</button>
  `).join('');
}

document.getElementById('menuCustomIngredient').addEventListener('click', (e) => {
  const btn = e.target.closest('[data-ingredient-id]');
  if (!btn) return;
  selectIngredient(btn.dataset.ingredientId);
});

function selectIngredient(id) {
  state.fuel.selectedIngredientId = id;
  document.getElementById('menuCustomIngredient').hidden = true;
  document.getElementById('btnCustomIngredientSelect').setAttribute('aria-expanded', 'false');
  renderNonNativeIngredientDropdown();

  const ing = state.fuel.foodDb.find(i => i.id === id);
  if (!ing || ing.id === 'custom') {
    resetMealSelection();
    return;
  }

  document.getElementById('inMealCategory').value = ing.defaultMeal || ing.cat || 'Lunch';
  syncCustomSelect(document.getElementById('inMealCategory'));
  document.getElementById('inPortionGrams').value = ing.defaultGrams || 100;
  recalculateIngredientMacros();
}

function toggleManageMealDropdown() {
  const menu = document.getElementById('menuCustomManageSelect');
  const btn = document.getElementById('btnCustomManageSelect');
  const willOpen = menu.hidden;
  closeAllCustomMenus(willOpen ? menu : null);
  menu.hidden = !willOpen;
  btn.setAttribute('aria-expanded', String(willOpen));
}

function selectableMeals() {
  return getSortedFoodDb(false);
}

function renderNonNativeManageDropdown() {
  const menu = document.getElementById('menuCustomManageSelect');
  const selectable = selectableMeals();
  const active = state.fuel.foodDb.find(i => i.id === state.fuel.selectedManageMealId);

  document.getElementById('lblCustomManageSelect').textContent = active ? active.name : 'Select a meal to edit';
  const summary = document.getElementById('fuelHeaderSummary');
  if (summary) summary.textContent = active ? `${active.name} · ${active.cals100} kcal/100g` : selectable.length ? `${selectable.length} meal${selectable.length === 1 ? '' : 's'} in your library` : 'Create your first meal';
  document.getElementById('copyAllMeals').disabled = !selectable.length;

  menu.innerHTML = selectable.length ? selectable.map(meal => `
    <button type="button" role="option" data-manage-meal-id="${esc(meal.id)}" aria-selected="${String(meal.id === active?.id)}">${meal.liked ? '♥ ' : ''}${esc(meal.name)}</button>
  `).join('') : '<span class="routine-menu-empty">No meals yet</span>';
}

document.getElementById('menuCustomManageSelect').addEventListener('click', (e) => {
  const btn = e.target.closest('[data-manage-meal-id]');
  if (!btn) return;
  selectManageMeal(btn.dataset.manageMealId);
});

function selectManageMeal(id) {
  state.fuel.selectedManageMealId = id;
  document.getElementById('menuCustomManageSelect').hidden = true;
  document.getElementById('btnCustomManageSelect').setAttribute('aria-expanded', 'false');
  renderNonNativeManageDropdown();
  loadMealIntoEditor();
}

function loadMealIntoEditor() {
  const meal = state.fuel.foodDb.find(m => m.id === state.fuel.selectedManageMealId);
  const form = document.getElementById('mealEditorForm');
  const modeButton = document.getElementById('fuelNewMealToggle');
  const likeBtn = document.getElementById('btnManageLike');
  const deleteBtn = document.getElementById('btnManageDelete');

  form.hidden = !meal;
  modeButton.querySelector('span').textContent = meal ? 'Save meal' : 'Add meal';
  modeButton.querySelector('use')?.setAttribute('href', meal ? '#icon-check' : '#icon-plus');
  modeButton.setAttribute('aria-label', meal ? 'Save meal' : 'Add meal');
  likeBtn.disabled = !meal;
  deleteBtn.disabled = !meal;
  document.getElementById('copyManagedMeal').disabled = !meal;
  document.getElementById('copyAllMeals').disabled = !selectableMeals().length;
  likeBtn.classList.toggle('liked', !!meal?.liked);
  likeBtn.setAttribute('aria-pressed', String(Boolean(meal?.liked)));

  if (!meal) return;

  document.getElementById('editMealName').value = meal.name;
  document.getElementById('editMealCat').value = meal.cat || 'Lunch';
  syncCustomSelect(document.getElementById('editMealCat'));
  document.getElementById('editMealDefaultGrams').value = meal.defaultGrams || 100;
  document.getElementById('editMealP').value = meal.p100;
  document.getElementById('editMealC').value = meal.c100;
  document.getElementById('editMealF').value = meal.f100;
  document.getElementById('editMealCals').value = meal.cals100 || Math.round((meal.p100 * 4) + (meal.c100 * 4) + (meal.f100 * 9));
}

function syncManagedMealCals() {
  const p = parseFloat(document.getElementById('editMealP').value) || 0;
  const c = parseFloat(document.getElementById('editMealC').value) || 0;
  const f = parseFloat(document.getElementById('editMealF').value) || 0;
  document.getElementById('editMealCals').value = Math.round((p * 4) + (c * 4) + (f * 9));
}

function toggleManageMealLike() {
  const meal = state.fuel.foodDb.find(m => m.id === state.fuel.selectedManageMealId);
  if (!meal) return;

  meal.liked = !meal.liked;
  saveFuelState();
  renderFuelDropdowns();
  renderLikedCards();
  loadMealIntoEditor();
  toast(meal.liked ? 'Added to quick cards ♥' : 'Removed from quick cards');
}

function initNewCustomMeal() {
  const newId = 'custom_' + Date.now();
  const newMeal = {
    id: newId,
    name: '',
    cat: 'Lunch',
    defaultMeal: 'Lunch',
    p100: 20,
    c100: 10,
    f100: 5,
    cals100: 165,
    defaultGrams: 100,
    liked: true
  };
  state.fuel.foodDb.unshift(newMeal);
  state.fuel.selectedManageMealId = newId;
  saveFuelState();
  renderFuelDropdowns();
  renderLikedCards();
  loadMealIntoEditor();
  requestAnimationFrame(() => document.getElementById('editMealName')?.focus());
  toast('New meal created');
}

function deleteManagedMeal() {
  const meal = state.fuel.foodDb.find(m => m.id === state.fuel.selectedManageMealId);
  if (!meal) return;

  if (confirm(`Delete "${meal.name || 'Unnamed meal'}" from your meal library?`)) {
    state.fuel.foodDb = state.fuel.foodDb.filter(m => m.id !== meal.id);
    state.fuel.selectedManageMealId = null;
    saveFuelState();
    renderFuelDropdowns();
    renderLikedCards();
    loadMealIntoEditor();
    toast('Meal removed');
  }
}

function mealManagerToggle() {
  if (state.fuel.foodDb.some(m => m.id === state.fuel.selectedManageMealId)) commitManagedMeal();
  else initNewCustomMeal();
}

function saveManagedMeal(e) {
  e.preventDefault();
  commitManagedMeal();
}

function commitManagedMeal() {
  const meal = state.fuel.foodDb.find(m => m.id === state.fuel.selectedManageMealId);
  if (!meal) return;

  const cleanName = document.getElementById('editMealName').value.trim();
  if (!cleanName) return toast('Name your meal first');
  meal.name = cleanName;
  meal.cat = document.getElementById('editMealCat').value;
  meal.defaultMeal = document.getElementById('editMealCat').value;
  meal.defaultGrams = Math.max(1, parseFloat(document.getElementById('editMealDefaultGrams').value) || 100);
  meal.p100 = parseFloat(document.getElementById('editMealP').value) || 0;
  meal.c100 = parseFloat(document.getElementById('editMealC').value) || 0;
  meal.f100 = parseFloat(document.getElementById('editMealF').value) || 0;

  let cals = parseInt(document.getElementById('editMealCals').value);
  if (isNaN(cals) || cals <= 0) {
    cals = Math.round((meal.p100 * 4) + (meal.c100 * 4) + (meal.f100 * 9));
  }
  meal.cals100 = cals;

  saveFuelState();
  state.fuel.selectedManageMealId = null;
  renderFuelDropdowns();
  renderLikedCards();
  loadMealIntoEditor();
  toast('Meal changes saved');
}

function mealToText(meal) {
  if (!meal) return '';
  return `${meal.name} - ${meal.cat || 'Other'} (${meal.defaultGrams || 100}g)\nPer100g ${meal.cals100}cal ${meal.p100}pro ${meal.c100}carb ${meal.f100}fat`;
}

function mealsToText() {
  return selectableMeals().map(mealToText).join('\n\n');
}

function parseMealsText(text) {
  const lines = String(text || '').replace(/\r/g, '').split('\n').map(line => line.trim()).filter(Boolean);
  if (!lines.length) throw new Error('Empty');
  const stamp = Date.now();
  const meals = [];
  let currentMeal = null;

  for (const line of lines) {
    const headerMatch = line.match(/^(.*?)\s*-\s*([A-Za-z0-9\/\s]+)\s*\(\s*(\d+(?:\.\d+)?)\s*g\s*\)$/i);
    if (headerMatch) {
      currentMeal = {
        id: `m-${stamp}-${meals.length}`,
        name: headerMatch[1].trim(),
        cat: headerMatch[2].trim(),
        defaultMeal: headerMatch[2].trim(),
        defaultGrams: clamp(headerMatch[3], 1, 5000),
        p100: 0,
        c100: 0,
        f100: 0,
        cals100: 0,
        liked: false
      };
      meals.push(currentMeal);
      continue;
    }

    const macroMatch = line.match(/^Per100g\s+(\d+(?:\.\d+)?)\s*cal\s+(\d+(?:\.\d+)?)\s*pro\s+(\d+(?:\.\d+)?)\s*carb\s+(\d+(?:\.\d+)?)\s*fat$/i);
    if (macroMatch && currentMeal) {
      currentMeal.cals100 = Math.round(Number(macroMatch[1]));
      currentMeal.p100 = clamp(macroMatch[2], 0, 999);
      currentMeal.c100 = clamp(macroMatch[3], 0, 999);
      currentMeal.f100 = clamp(macroMatch[4], 0, 999);
      continue;
    }
  }

  if (!meals.length || meals.some(m => !m.name)) throw new Error('Invalid meal format');
  return meals;
}

function showMealPastePanel(text = '') {
  $('#mealPastePanel').hidden = false;
  $('#pasteMealToggle').setAttribute('aria-expanded', 'true');
  if (text) $('#mealPasteText').value = text;
  requestAnimationFrame(() => { $('#mealPasteText').focus(); if (text) $('#mealPasteText').select(); });
}
function closeMealPastePanel() {
  $('#mealPastePanel').hidden = true;
  $('#pasteMealToggle').setAttribute('aria-expanded', 'false');
}
async function copyMealValue(text, successMessage) {
  try { await navigator.clipboard.writeText(text); toast(successMessage); }
  catch { showMealPastePanel(text); toast('Select and copy the text'); }
}
function importMealsFromText(mode = 'replace') {
  try {
    const imported = parseMealsText($('#mealPasteText').value);
    if (mode === 'add') {
      state.fuel.foodDb.push(...imported);
      toast(`${imported.length} meal${imported.length === 1 ? '' : 's'} added`);
    } else {
      if (selectableMeals().length && !confirm('Replace all existing custom meals with imported ones?')) return;
      const customItem = state.fuel.foodDb.find(i => i.id === 'custom') || DEFAULT_FOOD_DB[0];
      state.fuel.foodDb = [customItem, ...imported];
      toast(`${imported.length} meal${imported.length === 1 ? '' : 's'} imported`);
    }
    saveFuelState();
    renderFuelDropdowns();
    renderLikedCards();
    loadMealIntoEditor();
    $('#mealPasteText').value = '';
    closeMealPastePanel();
  } catch {
    toast('Use: Name - Category (100g)\\nPer100g 100cal 10pro 10carb 2fat');
  }
}

$('#copyManagedMeal').addEventListener('click', () => {
  const meal = state.fuel.foodDb.find(m => m.id === state.fuel.selectedManageMealId);
  meal ? copyMealValue(mealToText(meal), 'Meal copied') : toast('Select a meal first');
});
$('#copyAllMeals').addEventListener('click', () => {
  const meals = selectableMeals();
  meals.length ? copyMealValue(mealsToText(), 'All meals copied') : toast('Create a meal first');
});
$('#pasteMealToggle').addEventListener('click', () => $('#mealPastePanel').hidden ? showMealPastePanel() : closeMealPastePanel());
$('#cancelMealPaste').addEventListener('click', closeMealPastePanel);
$('#addMealText').addEventListener('click', () => importMealsFromText('add'));
$('#importMealText').addEventListener('click', () => importMealsFromText('replace'));

function renderLikedCards() {
  const container = document.getElementById('presetFoodContainer');
  const liked = getSortedFoodDb(false).filter(i => i.liked);

  let html = `
    <button type="button" class="preset-chip preset-chip-add" onclick="openLogMealForNew()" title="Add meal" aria-label="Add meal">
      <span class="preset-chip-add-content">
        <svg class="icon"><use href="#icon-plus"/></svg>
        <strong>Add</strong>
      </span>
    </button>
  `;

  liked.forEach(meal => {
    const grams = meal.defaultGrams || 100;
    const factor = grams / 100;
    const cals = Math.round(meal.cals100 * factor);
    html += `
      <button type="button" class="preset-chip" onclick="applyPresetIngredient('${meal.id}', ${grams})">
        <strong>${meal.name.split(',')[0]} (${grams}g)</strong>
        <span>${cals} kcal • P: ${(meal.p100 * factor).toFixed(0)}g</span>
      </button>
    `;
  });

  container.innerHTML = html;
}

function resetMealSelection() {
  state.fuel.selectedIngredientId = 'custom';
  renderNonNativeIngredientDropdown();
  document.getElementById('inPortionGrams').value = 100;
  document.getElementById('inFoodName').value = '';
  document.getElementById('inFoodP').value = '0.0';
  document.getElementById('inFoodC').value = '0.0';
  document.getElementById('inFoodF').value = '0.0';
  document.getElementById('inFoodCals').value = '0';
}

function setPortion(grams) {
  document.getElementById('inPortionGrams').value = grams;
  recalculateIngredientMacros();
}

function recalculateIngredientMacros() {
  const ing = state.fuel.foodDb.find(i => i.id === state.fuel.selectedIngredientId);
  if (!ing || ing.id === 'custom') return;

  const grams = Math.max(0, parseFloat(document.getElementById('inPortionGrams').value) || 0);
  const factor = grams / 100;

  const p = (ing.p100 * factor).toFixed(1);
  const c = (ing.c100 * factor).toFixed(1);
  const f = (ing.f100 * factor).toFixed(1);
  const cals = Math.round(ing.cals100 * factor);

  document.getElementById('inFoodName').value = `${ing.name.split(',')[0]} (${grams}g)`;
  document.getElementById('inFoodP').value = p;
  document.getElementById('inFoodC').value = c;
  document.getElementById('inFoodF').value = f;
  document.getElementById('inFoodCals').value = cals;
}

function applyPresetIngredient(id, grams) {
  state.fuel.selectedIngredientId = id;
  renderNonNativeIngredientDropdown();
  document.getElementById('inPortionGrams').value = grams;
  recalculateIngredientMacros();
  openOverlay('logMeal');
}

function syncFoodCalories() {
  const p = parseFloat(document.getElementById('inFoodP').value) || 0;
  const c = parseFloat(document.getElementById('inFoodC').value) || 0;
  const f = parseFloat(document.getElementById('inFoodF').value) || 0;
  const computed = Math.round((p * 4) + (c * 4) + (f * 9));
  document.getElementById('inFoodCals').value = computed;
}

document.getElementById('foodForm').addEventListener('click', (e) => {
  const btn = e.target.closest('.routine-step[data-food-field]');
  if (!btn) return;
  const field = btn.dataset.foodField;
  const delta = parseFloat(btn.dataset.foodDelta);

  if (field === 'cals') {
    const input = document.getElementById('inFoodCals');
    let val = Math.max(0, (parseInt(input.value) || 0) + delta);
    input.value = val;
  } else {
    const inputId = field === 'p' ? 'inFoodP' : field === 'c' ? 'inFoodC' : 'inFoodF';
    const input = document.getElementById(inputId);
    let val = Math.max(0, (parseFloat(input.value) || 0) + delta);
    input.value = (Math.round(val * 10) / 10).toFixed(1);
    syncFoodCalories();
  }
});

function handleFoodSubmit(e) {
  e.preventDefault();
  const name = document.getElementById('inFoodName').value.trim();
  const p = parseFloat(document.getElementById('inFoodP').value) || 0;
  const c = parseFloat(document.getElementById('inFoodC').value) || 0;
  const f = parseFloat(document.getElementById('inFoodF').value) || 0;
  let cals = parseInt(document.getElementById('inFoodCals').value);

  if (isNaN(cals) || cals <= 0) {
    cals = Math.round((p * 4) + (c * 4) + (f * 9));
  }
  const category = document.getElementById('inMealCategory').value;

  ensureDateRecord(state.fuelSelectedDate);
  state.fuel.history[state.fuelSelectedDate].meals.push({
    id: Date.now(),
    name,
    cals,
    p: Math.round(p * 10) / 10,
    c: Math.round(c * 10) / 10,
    f: Math.round(f * 10) / 10,
    category
  });

  saveFuelState();
  renderFuelDay();
  resetMealSelection();
  closeOverlay('logMeal');
  toast('Meal logged');
}

function deleteMeal(id) {
  ensureDateRecord(state.fuelSelectedDate);
  const targetMeal = state.fuel.history[state.fuelSelectedDate].meals.find(m => m.id === id);
  if (!confirm(`Delete meal "${targetMeal?.name || 'this item'}"?`)) return;
  state.fuel.history[state.fuelSelectedDate].meals = state.fuel.history[state.fuelSelectedDate].meals.filter(m => m.id !== id);
  saveFuelState();
  renderFuelDay();
  toast('Meal removed');
}

function addWater(amount) {
  ensureDateRecord(state.fuelSelectedDate);
  state.fuel.history[state.fuelSelectedDate].water += amount;
  saveFuelState();
  renderFuelDay();
}

function resetWater() {
  ensureDateRecord(state.fuelSelectedDate);
  state.fuel.history[state.fuelSelectedDate].water = 0;
  saveFuelState();
  renderFuelDay();
}

function renderFuelDay() {
  ensureDateRecord(state.fuelSelectedDate);
  const day = state.fuel.history[state.fuelSelectedDate];

  const today = localDateValue();
  const isToday = state.fuelSelectedDate === today;
  const parts = state.fuelSelectedDate.split('-').map(Number);
  const dObj = new Date(parts[0], parts[1] - 1, parts[2]);
  const formattedDate = dObj.toLocaleDateString('fa-IR-u-ca-gregory', { weekday: 'long', month: 'short', day: 'numeric' });
  document.getElementById('dailyBalanceDateEyebrow').innerText = formattedDate;

  const btnReset = document.getElementById('btnResetToday');
  if (btnReset) btnReset.disabled = isToday;
  const btnNext = document.getElementById('btnNextDay');
  if (btnNext) btnNext.disabled = isToday;

  const foodTotals = day.meals.reduce((acc, m) => {
    acc.cals += Number(m.cals) || 0;
    acc.p += Number(m.p) || 0;
    acc.c += Number(m.c) || 0;
    acc.f += Number(m.f) || 0;
    return acc;
  }, { cals: 0, p: 0, c: 0, f: 0 });

  const goalCals = state.fuel.profile.dailyCalorieGoal;
  const remaining = goalCals - foodTotals.cals;

  document.getElementById('lblTargetCalorieGoal').innerText = `Goal: ${goalCals.toLocaleString()} kcal`;
  document.getElementById('calsRemaining').innerText = Math.abs(remaining).toLocaleString();
  document.getElementById('calsRemainingSub').innerText = remaining >= 0 ? 'kcal left' : 'kcal over';

  const circ = 282.74;
  const pct = Math.min(foodTotals.cals / goalCals, 1);
  document.getElementById('calMeter').style.strokeDashoffset = circ - (pct * circ);
  document.getElementById('calMeter').style.stroke = remaining < 0 ? 'var(--danger)' : 'var(--accent)';

  const updateBar = (id, current, goal) => {
    document.getElementById(`meta${id}`).innerText = `${Math.round(current)} / ${goal}g`;
    document.getElementById(`bar${id}`).style.width = `${Math.min((current / goal) * 100, 100)}%`;
  };
  updateBar('Protein', foodTotals.p, state.fuel.profile.macros.p);
  updateBar('Carbs', foodTotals.c, state.fuel.profile.macros.c);
  updateBar('Fats', foodTotals.f, state.fuel.profile.macros.f);

  const waterGoal = state.fuel.profile.dailyWaterMl;
  document.getElementById('waterDisplay').innerText = `${day.water.toLocaleString()} / ${waterGoal.toLocaleString()} ml`;
  document.getElementById('waterBar').style.width = `${Math.min((day.water / waterGoal) * 100, 100)}%`;

  const categories = ['Breakfast', 'Lunch', 'Dinner', 'Snacks'];
  const container = document.getElementById('mealsContainer');

  if (day.meals.length === 0) {
    container.innerHTML = '<div class="feature-empty">هیچ وعده‌ای برای این روز ثبت نشده است.</div>';
  } else {
    container.innerHTML = categories.map(cat => {
      const items = day.meals.filter(m => m.category === cat);
      if (items.length === 0) return '';
      const catCals = items.reduce((s, i) => s + (Number(i.cals) || 0), 0);

      return `
        <div class="meal-group">
          <div class="meal-group-head">
            <h4>${cat}</h4>
            <span>${catCals} kcal</span>
          </div>
          ${items.map(i => `
            <article class="progress-entry" data-meal-id="${i.id}">
              <div class="progress-entry-date"><b>${i.cals}</b><span>KCAL</span></div>
              <div class="progress-entry-copy">
                <strong>${esc(i.name)}</strong>
                <span>P: ${i.p}g · C: ${i.c}g · F: ${i.f}g</span>
              </div>
              <button class="entry-delete" type="button" onclick="deleteMeal(${i.id})" aria-label="Delete ${esc(i.name)}">
                ${icon('trash')}
              </button>
            </article>
          `).join('')}
        </div>
      `;
    }).join('');
  }
}

function renderAll() {
  renderFuelDay();
  renderBodySection();
}

function renderBodySection() {
  const p = state.fuel.profile;
  const hM = p.heightCm / 100;
  const bmi = (p.currentWeightKg / (hM * hM)).toFixed(1);

  document.getElementById('bmiValDisplay').innerText = bmi;
  document.getElementById('weightValDisplay').innerText = p.currentWeightKg.toFixed(1) + ' کیلوگرم';

  const badge = document.getElementById('bmiBadge');
  badge.className = 'bmi-badge ';
  if (bmi < 18.5) { badge.classList.add('bmi-under'); badge.innerText = 'Underweight'; }
  else if (bmi < 25) { badge.classList.add('bmi-normal'); badge.innerText = 'Normal'; }
  else if (bmi < 30) { badge.classList.add('bmi-over'); badge.innerText = 'Overweight'; }
  else { badge.classList.add('bmi-obese'); badge.innerText = 'Obese'; }

  const minHealthyKg = (18.5 * (hM * hM)).toFixed(1);
  const maxHealthyKg = (24.9 * (hM * hM)).toFixed(1);
  document.getElementById('idealWeightSpan').innerText = `${minHealthyKg} – ${maxHealthyKg} کیلوگرم`;

  document.getElementById('lblStartWeight').innerText = p.startWeightKg.toFixed(1) + ' کیلوگرم';
  document.getElementById('lblGoalWeight').innerText = p.goalWeightKg.toFixed(1) + ' کیلوگرم';

  const isWeightLoss = p.startWeightKg > p.goalWeightKg;
  const isWeightGain = p.startWeightKg < p.goalWeightKg;
  let pct = 0;

  if (isWeightLoss) {
    const totalSpan = p.startWeightKg - p.goalWeightKg;
    const progressDone = p.startWeightKg - p.currentWeightKg;
    pct = Math.max(0, Math.min(100, Math.round((progressDone / totalSpan) * 100)));
  } else if (isWeightGain) {
    const totalSpan = p.goalWeightKg - p.startWeightKg;
    const progressDone = p.currentWeightKg - p.startWeightKg;
    pct = Math.max(0, Math.min(100, Math.round((progressDone / totalSpan) * 100)));
  } else {
    pct = 100;
  }

  document.getElementById('barWeightGoal').style.width = `${pct}%`;
  document.getElementById('goalPercentText').innerText = `${pct}% complete`;

  const remainingDiff = Math.abs(p.goalWeightKg - p.currentWeightKg).toFixed(1);
  if (parseFloat(remainingDiff) === 0) {
    document.getElementById('weightDeltaDisplay').innerText = `Goal Achieved!`;
  } else if (p.currentWeightKg > p.goalWeightKg) {
    document.getElementById('weightDeltaDisplay').innerText = `${remainingDiff} kg to lose`;
  } else {
    document.getElementById('weightDeltaDisplay').innerText = `${remainingDiff} kg to gain`;
  }
}

document.getElementById('bodyMetricsModal').addEventListener('click', (e) => {
  const stepBtn = e.target.closest('.routine-step[data-target]');
  if (!stepBtn) return;
  const targetId = stepBtn.dataset.target;
  const delta = parseFloat(stepBtn.dataset.delta);
  const input = document.getElementById(targetId);
  if (!input) return;

  let val = parseFloat(input.value) || 0;
  const minVal = targetId === 'inAge' ? 10 : 30;
  const maxVal = targetId === 'inAge' ? 110 : 300;
  val = Math.max(minVal, Math.min(maxVal, val + delta));
  input.value = targetId === 'inAge' || targetId === 'inHeight' ? Math.round(val) : val.toFixed(1);
});

function handleProfileAndTargetSubmit(e) {
  e.preventDefault();

  const age = parseInt(document.getElementById('inAge').value) || 22;
  const sex = document.getElementById('inSex').value;
  const heightCm = parseFloat(document.getElementById('inHeight').value) || 178;
  const currentWeightKg = parseFloat(document.getElementById('inCurrentWeight').value) || 75.0;
  const startWeightKg = parseFloat(document.getElementById('inStartWeight').value) || currentWeightKg;
  const goalWeightKg = parseFloat(document.getElementById('inGoalWeight').value) || currentWeightKg;

  const activity = parseFloat(document.getElementById('inActivity').value) || 1.55;
  const strategy = parseInt(document.getElementById('inStrategy').value) || 0;
  const proteinRate = parseFloat(document.getElementById('inProteinRate').value) || 2.0;

  const bmr = (10 * currentWeightKg) + (6.25 * heightCm) - (5 * age) + (sex === 'm' ? 5 : -161);
  const tdee = Math.round(bmr * activity);
  let targetCalories = Math.max(1200, Math.round(tdee + strategy));

  const pGrams = Math.round(currentWeightKg * proteinRate);
  const proteinCals = pGrams * 4;
  const fGrams = Math.round((targetCalories * 0.25) / 9);
  const fatCals = fGrams * 9;
  const remainingCalsForCarbs = Math.max(0, targetCalories - (proteinCals + fatCals));
  const cGrams = Math.round(remainingCalsForCarbs / 4);

  targetCalories = (pGrams * 4) + (cGrams * 4) + (fGrams * 9);
  const waterMl = Math.round(Math.max(2000, currentWeightKg * (activity >= 1.50 ? 45 : 35)));

  state.fuel.profile = {
    age, sex, heightCm, currentWeightKg, startWeightKg, goalWeightKg,
    activity, strategy, proteinRate,
    dailyCalorieGoal: targetCalories,
    dailyWaterMl: waterMl,
    macros: { p: pGrams, c: cGrams, f: fGrams }
  };

  saveFuelState();
  renderAll();
  closeOverlay('bodyMetrics');
  toast(`Targets updated: ${targetCalories} kcal (P: ${pGrams}g, C: ${cGrams}g, F: ${fGrams}g)`);
}

renderFuelDropdowns();
renderLikedCards();
renderAll();

